using System;using System.Linq;using System.Collections.Generic;
public static class ArchiveTimeline {
 public static DateTime Start(DateTime day,int range){return range==0?day.Date:TrafficHistory.Start(day,range==2);}
 public static DateTime End(DateTime start,int range){return range==0?start.AddDays(1):range==1?start.AddDays(7):start.AddMonths(1);}
 public static DateTime[] Dates(DateTime start,DateTime end,int minutes){if(minutes!=1&&minutes!=5&&minutes!=60&&minutes!=1440)throw new ArgumentException("不支持的时间粒度");return Enumerable.Range(0,(int)Math.Ceiling((end-start).TotalMinutes/minutes)).Select(i=>start.AddMinutes((double)i*minutes)).ToArray();}
 public static double?[] Values(DateTime[] dates,int minutes,string key,MinutePoint[] points,ArchiveHour[] hours,bool peak){var buckets=new List<double>[dates.Length];for(int i=0;i<buckets.Length;i++)buckets[i]=new List<double>();if(dates.Length==0)return new double?[0];foreach(var p in points){int index=(int)Math.Floor((p.Utc.ToLocalTime()-dates[0]).TotalMinutes/minutes);double value;if(index>=0&&index<buckets.Length&&p.Values.TryGetValue(key,out value))buckets[index].Add(value);}var old=new List<ArchiveMetric>[dates.Length];for(int i=0;i<old.Length;i++)old[i]=new List<ArchiveMetric>();if(minutes>=60)foreach(var h in hours){int index=(int)Math.Floor((h.Utc.ToLocalTime()-dates[0]).TotalMinutes/minutes);ArchiveMetric metric;if(index>=0&&index<old.Length&&h.Metrics.TryGetValue(key,out metric)&&metric.Weight>0)old[index].Add(metric);}bool quota=key=="codex5h"||key=="codex7d";return Enumerable.Range(0,dates.Length).Select(i=>buckets[i].Count>0?(double?)(quota?buckets[i].Last():peak?buckets[i].Max():buckets[i].Average()):old[i].Count>0?(double?)(peak?old[i].Max(m=>m.Peak):old[i].Sum(m=>m.Sum)/old[i].Sum(m=>m.Weight)):null).ToArray();}
}
